import { Client, Wallet } from 'xrpl'
const c = new Client('wss://s.altnet.rippletest.net:51233'); await c.connect()
const w = Wallet.fromSeed('<TESTNET_SEED_REDACTED>')
const holders = JSON.parse(readFileSync('data/rehearsal/holders.json', 'utf8'))
const A = Wallet.fromSeed(holders.A.seed)
const id = '01427786B941F6569FDC635E2ED4440CD801AA80283658C4'
const run = async (wallet, tx) => { const r = await c.submitAndWait(tx, { wallet, autofill: true }); return r.result.meta.TransactionResult }
const redeem = { TransactionType: 'Payment', Account: A.classicAddress, Destination: w.classicAddress, Amount: { mpt_issuance_id: id, value: '1' } }
console.log('lock A', await run(w, { TransactionType: 'MPTokenIssuanceSet', Account: w.classicAddress, MPTokenIssuanceID: id, Holder: A.classicAddress, Flags: 1 }))
console.log('locked A -> issuer', await run(A, redeem))
console.log('unlock A', await run(w, { TransactionType: 'MPTokenIssuanceSet', Account: w.classicAddress, MPTokenIssuanceID: id, Holder: A.classicAddress, Flags: 2 }))
