import { readFileSync } from 'node:fs'
import { Client } from 'xrpl'
const r = JSON.parse(readFileSync('result.json', 'utf8'))
const c = new Client('wss://s.altnet.rippletest.net:51233'); await c.connect()
const objs = (await c.request({ command: 'account_objects', account: 'r9e83mrK9Ps69gVixqhbx8kEULvDB7RAvk', ledger_index: 'validated' })).result.account_objects
console.log('issuer objects:', objs.map((o) => `${o.LedgerEntryType} ${o.mpt_issuance_id ?? ''} Flags=0x${o.Flags.toString(16)} Outstanding=${o.OutstandingAmount}`))
for (const [k, a] of Object.entries(r.holders)) {
  const t = (await c.request({ command: 'account_objects', account: a, type: 'mptoken', ledger_index: 'validated' })).result.account_objects
  console.log(k, a, t.map((o) => `MPT=${o.MPTokenIssuanceID === r.issuanceId} MPTAmount=${o.MPTAmount ?? 0} Flags=0x${o.Flags.toString(16)}`))
}
const bal = (await c.request({ command: 'account_info', account: 'r9e83mrK9Ps69gVixqhbx8kEULvDB7RAvk', ledger_index: 'validated' })).result.account_data.Balance
console.log('issuer XRP', Number(bal) / 1e6)
await c.disconnect()

